def settle_legacy_transfers(apps, schema_editor):
    """Before this migration dispatch moved stock straight into the
    destination, so an old 'In Transit' transfer has already arrived. Record
    it as dispatched and received so nothing is moved twice."""
    from django.db.models import F

    Transfer = apps.get_model("inventory", "StockTransfer")
    Line = apps.get_model("inventory", "StockTransferLine")
    moved = Transfer.objects.filter(status__in=["In Transit", "Received", "Completed"])
    Line.objects.filter(stock_transfer__in=moved).update(
        dispatched_qty=F("qty"), received_qty=F("qty")
    )
    moved.filter(status="In Transit").update(status="Received")


Migration.operations.append(
    migrations.RunPython(settle_legacy_transfers, migrations.RunPython.noop)
)
